// Integration math: bespoke vs standard (plain JS)
function bespoke(hosts, sources) { return hosts * sources; }
function standard(hosts, sources) { return hosts + sources; }
console.log("bespoke 12x8: " + bespoke(12, 8));   // 96 wirings
console.log("standard 12x8: " + standard(12, 8)); // 20 implementations
